register_shutdown_function(static function():void{if(!isset($GLOBALS['db'],$GLOBALS['p'])||!preg_match('/^essential_[a-f0-9]{10}_$/D',$GLOBALS['p']))return;foreach(['company_portal_support_requests','company_portal_support_replies','company_portal_support_origins','company_portal_contracts_files','company_portal_tickets_files','company_portal_projects_files','company_portal_ticket_replies','company_portal_contracts','company_portal_tickets','company_portal_projects','company_portal_operation_requests','company_contract_files','company_ticket_files'] as $suffix){$db=$GLOBALS['db'];if($db->table_exists($GLOBALS['p'].$suffix))$db->query('DROP TABLE '.$GLOBALS['p'].$suffix);}});
